-- In production this module is generated by the runner; here it is handwritten.
module Main (main) where

import Defs
import qualified Judge
import Student

main :: IO ()
main =
  Judge.runTests
    [ Judge.Test (total []) (0)
    , Judge.Test (total [1, 2, 3]) (6)
    , Judge.Test (reversed "hello") ("olleh")
    , Judge.Test (inOrder (Node (Node Leaf 1 Leaf) 2 (Node Leaf 3 Leaf))) ([1, 2, 3])
    , Judge.Test (depth (Node Leaf 'a' (Node Leaf 'b' Leaf))) (2)
    , Judge.Test (total [1 .. 1000000]) (500000500000)
    ]
